<?php
require 'config.php'; require_login();$id=max(0,(int)($_GET['run_id']??0));$st=$pdo->prepare('SELECT r.*,s.name,s.start_url FROM scan_runs r JOIN sites s ON s.id=r.site_id WHERE r.id=?');$st->execute([$id]);$run=$st->fetch();if(!$run){flash('Không tìm thấy phiên quét.','warning');redirect('history.php');}
$filter=$_GET['status']??'all';if(!in_array($filter,['all','errors','ok','redirect','unknown','unchecked','missing_anchor'],true))$filter='all';$q=trim((string)($_GET['q']??''));$typeFilter=(string)($_GET['type']??'all');if(!in_array($typeFilter,['all','page','link','image','resource'],true))$typeFilter='all';$page=max(1,(int)($_GET['page']??1));$per=20;$where=' WHERE f.run_id=?';$args=[$id];if($filter==='errors')$where.=" AND f.status_category IN ('http_error','connection_error','missing_anchor')";elseif($filter!=='all'){$where.=' AND f.status_category=?';$args[]=$filter;}if($typeFilter!=='all'){$where.=' AND f.resource_type=?';$args[]=$typeFilter;}if($q!==''){$where.=' AND (f.normalized_url LIKE ? OR f.error_detail LIKE ? OR l.source_url LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);}
$count=$pdo->prepare('SELECT COUNT(DISTINCT f.id) FROM findings f LEFT JOIN links l ON l.run_id=f.run_id AND l.normalized_url=f.base_target_url'.$where);$count->execute($args);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$sql='SELECT f.*, GROUP_CONCAT(DISTINCT CONCAT(l.source_url," (dòng ",l.line_number,")") SEPARATOR " | ") source_pages, MAX(l.line_number) line_number, MAX(l.tag_snippet) tag_snippet FROM findings f LEFT JOIN links l ON l.run_id=f.run_id AND l.normalized_url=f.base_target_url'.$where.' GROUP BY f.id ORDER BY CASE f.status_category WHEN "http_error" THEN 1 WHEN "missing_anchor" THEN 2 WHEN "connection_error" THEN 3 WHEN "unknown" THEN 4 WHEN "unchecked" THEN 5 WHEN "redirect" THEN 6 ELSE 7 END,f.id LIMIT '.$per.' OFFSET '.(($page-1)*$per);$st=$pdo->prepare($sql);$st->execute($args);$findings=$st->fetchAll();
$counts=$pdo->prepare('SELECT status_category,COUNT(*) amount FROM findings WHERE run_id=? GROUP BY status_category');$counts->execute([$id]);$summary=['ok'=>0,'redirect'=>0,'http_error'=>0,'connection_error'=>0,'missing_anchor'=>0,'unknown'=>0,'unchecked'=>0];foreach($counts->fetchAll() as $c)$summary[$c['status_category']]=(int)$c['amount'];$errorCount=$summary['http_error']+$summary['connection_error']+$summary['missing_anchor'];
layout_start('Báo cáo quét'); ?>
<div class="d-flex justify-content-between align-items-start flex-wrap gap-3 mb-4"><div><div class="small-label mb-2">BÁO CÁO CHI TIẾT</div><h1 class="h3 page-title mb-1">Phiên quét #<?=e($run['id'])?></h1><div class="muted"><?=e($run['name'])?> · <span class="wrap-url"><?=e($run['start_url'])?></span></div></div><div class="d-flex flex-wrap gap-2"><a class="btn btn-outline-secondary" href="history.php">← Lịch sử</a><a class="btn btn-success" href="export.php?run_id=<?=(int)$id?>">↓ Xuất CSV</a><a class="btn btn-outline-primary" href="pdf.php?run_id=<?=(int)$id?>" target="_blank" rel="noopener">Báo cáo PDF</a></div></div>
<div class="row g-3 mb-4"><?php foreach([['Trang đã quét',(int)$run['total_pages_crawled'],'#eef2ff','📄'],['Liên kết tìm thấy',(int)$run['total_links_found'],'#e0f2fe','↗'],['Đích hoạt động',$summary['ok'],'#dcfce7','✓'],['Đích lỗi',$errorCount,'#fee2e2','⚠']] as $m):?><div class="col-6 col-xl-3"><div class="card p-3 h-100"><div class="d-flex justify-content-between"><div class="muted small"><?=e($m[0])?></div><span style="background:<?=e($m[2])?>;padding:8px 10px;border-radius:12px"><?=e($m[3])?></span></div><div class="metric mt-2"><?=number_format($m[1])?></div></div></div><?php endforeach;?></div>
<div class="row g-3 mb-4"><div class="col-lg-7"><div class="card p-4 h-100"><h2 class="h5 fw-bold mb-3">Phân bố kết quả</h2><div style="max-width:520px;margin:0 auto 18px"><canvas id="statusChart" aria-label="Biểu đồ phân bố kết quả" role="img"></canvas></div><?php $den=max(1,array_sum($summary));foreach([['Hoạt động',$summary['ok'],'success'],['Chuyển hướng',$summary['redirect'],'warning'],['Lỗi HTTP',$summary['http_error'],'danger'],['Lỗi kết nối',$summary['connection_error'],'danger'],['Anchor lỗi',$summary['missing_anchor'],'danger'],['Chưa xác định',$summary['unknown'],'secondary'],['Bỏ qua / ngoài phạm vi',$summary['unchecked'],'secondary']] as $m):?><div class="d-flex justify-content-between small mb-2"><span><?=e($m[0])?></span><strong><?=$m[1]?> · <?=round($m[1]*100/$den)?>%</strong></div><div class="progress mb-3"><div class="progress-bar bg-<?=$m[2]?>" style="width:<?=round($m[1]*100/$den)?>%"></div></div><?php endforeach;?></div></div><div class="col-lg-5"><div class="card p-4 h-100"><h2 class="h5 fw-bold mb-3">Thông tin phiên</h2><p class="mb-2"><strong>Trạng thái:</strong> <?=e($run['status'])?></p><p class="mb-2"><strong>Bắt đầu:</strong> <?=e($run['started_at'])?></p><p class="mb-2"><strong>Kết thúc:</strong> <?=e($run['finished_at']??'—')?></p><p class="mb-0"><strong>Lý do dừng:</strong> <?=e($run['stop_reason']??'—')?></p></div></div></div>
<div class="card p-3 p-md-4"><div class="d-flex justify-content-between flex-wrap gap-2 mb-3"><div><h2 class="h5 fw-bold mb-1">Chi tiết liên kết</h2><p class="small muted mb-0">Có lưu trang nguồn, dòng HTML và đoạn thẻ để hỗ trợ sửa lỗi.</p></div><form method="get" class="row g-2 no-print"><input type="hidden" name="run_id" value="<?=$id?>"><div class="col"><input class="form-control form-control-sm" name="q" value="<?=e($q)?>" placeholder="Tìm URL, trang nguồn, lỗi"></div><div class="col"><select class="form-select form-select-sm" name="type"><option value="all" <?=$typeFilter==='all'?'selected':''?>>Mọi loại</option><option value="page" <?=$typeFilter==='page'?'selected':''?>>Trang</option><option value="link" <?=$typeFilter==='link'?'selected':''?>>Liên kết</option><option value="image" <?=$typeFilter==='image'?'selected':''?>>Ảnh</option><option value="resource" <?=$typeFilter==='resource'?'selected':''?>>Tài nguyên</option></select></div><div class="col"><select class="form-select form-select-sm" name="status"><option value="all" <?=$filter==='all'?'selected':''?>>Tất cả</option><option value="errors" <?=$filter==='errors'?'selected':''?>>Lỗi</option><option value="ok" <?=$filter==='ok'?'selected':''?>>Hoạt động</option><option value="redirect" <?=$filter==='redirect'?'selected':''?>>Chuyển hướng</option><option value="unknown" <?=$filter==='unknown'?'selected':''?>>Chưa xác định</option><option value="unchecked" <?=$filter==='unchecked'?'selected':''?>>Bỏ qua</option><option value="missing_anchor" <?=$filter==='missing_anchor'?'selected':''?>>Anchor lỗi</option></select></div><div class="col-auto"><button class="btn btn-sm btn-outline-primary">Lọc</button></div></form></div>
<div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>URL đích</th><th>Loại</th><th>HTTP</th><th>Kết quả</th><th>Trang nguồn / dòng</th><th>Chi tiết</th></tr></thead><tbody><?php if(!$findings):?><tr><td colspan="6" class="text-center py-5 muted">Không có kết quả phù hợp.</td></tr><?php endif;foreach($findings as $f):$good=$f['status_category']==='ok';$redirectStatus=$f['status_category']==='redirect';?><tr class="<?=$good?'status-row-ok':(!$redirectStatus?'status-row-error':'')?>"><td class="wrap-url"><a href="<?=e($f['normalized_url'])?>" target="_blank" rel="noopener noreferrer" class="text-decoration-none"><?=e($f['normalized_url'])?></a><?php if($f['fragment']):?><div class="small muted">Fragment: #<?=e($f['fragment'])?></div><?php endif;?></td><td><?=e($f['resource_type'])?></td><td><?=e($f['http_status']??'—')?></td><td><span class="badge text-bg-<?=$good?'success':($redirectStatus?'warning':(in_array($f['status_category'],['unknown','unchecked'])?'secondary':'danger'))?>"><?=e($f['status_category'])?></span></td><td class="wrap-url small"><?php if($f['source_pages']):?><?=e($f['source_pages'])?><?php else:?>—<?php endif;?><?php if($f['tag_snippet']):?><details class="mt-1"><summary>Xem thẻ HTML</summary><code><?=e($f['tag_snippet'])?></code></details><?php endif;?></td><td><?=e($f['error_detail'])?><?php if(in_array($f['status_category'],['http_error','connection_error','missing_anchor','unknown'],true)):?><?php if((current_user()['role']??'')==='admin'): ?><form method="post" action="retry.php" class="mt-2 no-print"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="run_id" value="<?=$id?>"><input type="hidden" name="finding_id" value="<?=(int)$f['id']?>"><button class="btn btn-sm btn-outline-secondary">Kiểm tra lại</button></form><?php endif; endif;?><?php if($f['redirect_chain']):?><div class="small muted">Redirect: <?=e($f['redirect_chain'])?></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mt-3"><div class="small muted">Tổng <?=$total?> kết quả · Trang <?=$page?>/<?=$pages?></div><div class="d-flex gap-2"><?php if($page>1):?><a class="btn btn-sm btn-outline-secondary" href="?run_id=<?=$id?>&status=<?=e($filter)?>&type=<?=e($typeFilter)?>&q=<?=urlencode($q)?>&page=<?=$page-1?>">← Trước</a><?php endif;?><?php if($page<$pages):?><a class="btn btn-sm btn-outline-secondary" href="?run_id=<?=$id?>&status=<?=e($filter)?>&type=<?=e($typeFilter)?>&q=<?=urlencode($q)?>&page=<?=$page+1?>">Tiếp →</a><?php endif;?></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script><script>
const chartNode=document.getElementById('statusChart');
if(chartNode && window.Chart){new Chart(chartNode,{type:'doughnut',data:{labels:['Hoạt động','Chuyển hướng','Lỗi HTTP','Lỗi kết nối','Anchor lỗi','Chưa xác định','Bỏ qua'],datasets:[{data:[<?= (int)$summary['ok']?>,<?= (int)$summary['redirect']?>,<?= (int)$summary['http_error']?>,<?= (int)$summary['connection_error']?>,<?= (int)$summary['missing_anchor']?>,<?= (int)$summary['unknown']?>,<?= (int)$summary['unchecked']?>]}]},options:{responsive:true,plugins:{legend:{position:'bottom'}}}});}
</script><style>@media print{nav,footer,form,.btn,.no-print{display:none!important}body{background:#fff!important}.card{box-shadow:none!important;border:1px solid #ddd!important;break-inside:avoid}.table{font-size:9px}.wrap-url{max-width:220px}a{text-decoration:none;color:#111}}</style><?php layout_end(); ?>